function translate(html) {
    'use strict';

    return String(html).replace(/\[\$(\w+)(?:\.(\w+))?]/g, (match, localeNum, ns) => {

        if (ns) {
            match = `${localeNum}.${ns}`;
            localeNum = match;
        }

        return `${l[localeNum] || ''}`;
    });
}

function isValidEmail(email) {
    'use strict';
    const input = document.createElement('input');
    input.type = 'email';
    input.value = email;
    return input.value.trim() && input.checkValidity();
}

function loadSubPage(page, ev) {
    'use strict';
    return T.ui.loadPage(page, ev);
}

window.addEventListener('popstate', (ev) => {
    'use strict';
    const state = ev.state || false;
    T.ui.loadPage(state.subpage || getCleanSitePath(), ev);
}, {
    capture: true,
    passive: true,
});

window.addEventListener('beforeunload', (ev) => {
    'use strict';

    if ('rad' in mega) {
        mega.rad.flush().dump('rad.flush');
    }

    if (T.ui.addFilesLayout.hasTransfers) {
        ev.preventDefault();
        ev.returnValue = true;
        return l[761] || '-';
    }

    mBroadcaster.crossTab.leave();

}, { capture: true });


