    return (key, value) => {
        let res = map[value];
        if (res !== undefined) {
            return res;
        }

        res = parseFloat(value);
        if (res === Number(value) && Number.isFinite(res)) {
            return res;
        }

        // if (key && key.endsWith('Date')) {
        //     value = Date.parse(value);
        // }

        return value;
    };
